INSERT INTO "Patients" ("Id", "GlobalUserId", "Phone", "EmergencyPhone", "Address", "AgeRange", "RelationshipStatus", "Occupation", "LivingSituation", "PrimaryGoal", "HasPreviousTherapy") VALUES ('03ada279-9096-5d76-842a-5fbb62dd9dfc', '8e41cfe4-3250-5a3a-90fa-ecb1c5becb2d', '+2222222222', '+2222222223', 'Calle 100', '45-55', 'Casado', 'Empresario', 'Vive con familia', 'Manejo de consumo de alcohol', TRUE);
INSERT INTO "Treatments" ("Id", "PatientId", "State", "SessionDay") VALUES ('12b01eac-bec4-5767-96bb-f447917bb7b1', 'a3848861-f20d-5e44-b2ea-ce55a1a62dbf', 'InProcess', 'monday');
INSERT INTO "Treatments" ("Id", "PatientId", "State", "SessionDay") VALUES ('323ff4ff-30b3-5eec-b040-3b5e48459be0', '03ada279-9096-5d76-842a-5fbb62dd9dfc', 'InProcess', 'monday');
INSERT INTO "Journalings" ("Id", "TreatmentId", "Date", "EntryType", "Transcription", "AiReplyText", "State") VALUES ('974429df-2bec-5299-b7a0-17dde5005ce4', '12b01eac-bec4-5767-96bb-f447917bb7b1', '2026-06-15', 'text', 'Día 1: Hoy fue un día realmente complicado... Me desperté sintiéndome bien, pero ya en la tarde, no sé, las ganas de ver videos en YouTube me invadieron. Empecé a navegar sin parar y, al final del día, me di cuenta de que había pasado horas y horas sin hacer nada productivo. Me sentía horrible, como si estuviera en una especie de agujero negro. No puedo creer que desperdicié otro día así. Mi madre me llamó la atención porque no tenía ganas de salir, y eso me molestó un poco. La lucha interna es real... la idea de dejarlo todo es aterradora, pero sé que tengo que hacerlo, o sino, ¿qué tipo de futuro voy a tener? A veces, no sé realmente qué quiero, y eso me frustra aún más...', 'Es completamente comprensible que te sientas abrumada después de un día así. Es un primer paso reconocer el tiempo que pasas en redes sociales y la frustración que sientes. Es normal luchar con estos impulsos, sobre todo cuando estás tratando de cambiar tu rutina. Recuerda que el camino hacia la recuperación no siempre es lineal; los retrocesos son parte del proceso. Sé amable contigo misma mientras navegas por estas emociones.', 'Processed');
INSERT INTO "Journalings" ("Id", "TreatmentId", "Date", "EntryType", "Transcription", "AiReplyText", "State") VALUES ('6dc2bbc8-b552-5035-8829-3cae9b5013c2', '12b01eac-bec4-5767-96bb-f447917bb7b1', '2026-06-16', 'audio', 'Día 2: Hoy intenté hacer un esfuerzo y limitar mi tiempo en el celular. Me propuse, eh, solo revisar las redes sociales por 30 minutos, pero no sé cómo, pero terminé pasándome. Me siento como que no tengo control... Lamentablemente, fue un día sin muchas actividades, así que regresé al mismo ciclo. Fui a dar una vuelta con mis padres, pero no pude evitar pensar en lo que me estaba perdiendo en línea. Hay un montón de amigos que suben fotos y videos de sus vidas, y me siento un poco excluida. Intento recordar que mi vida también es valiosa, pero es difícil mantener esa perspectiva cuando veo lo que otros hacen...', 'Es completamente normal que te sientas atrapada entre el deseo de desconectarte y la tentación de estar al tanto de lo que hacen los demás. La comparativa social puede ser muy abrumadora y es genial que estés intentando poner límites. Recuerda que establecer metas pequeñas y alcanzables es clave en este proceso. No te desanimes por los tropiezos. Cada día es una nueva oportunidad para aprender y mejorar.', 'Processed');
INSERT INTO "Journalings" ("Id", "TreatmentId", "Date", "EntryType", "Transcription", "AiReplyText", "State") VALUES ('b8c7e755-579a-5efa-931a-2266d8d527ef', '12b01eac-bec4-5767-96bb-f447917bb7b1', '2026-06-17', 'audio', 'Día 3: Hoy fue el día más difícil hasta ahora. Honestamente, no sé por qué, pero me desperté sintiéndome deprimida. Pasé todo el día encerrada en mi habitación, decepcionada de mí misma. Cada vez que pensaba en salir de este ciclo, el miedo y la ansiedad me paralizaban. Al final, acabé jugando un videojuego durante tres horas seguidas... Fue un escape, y aunque disfruté esos momentos, me di cuenta de que, al final, no soluciona nada. Me siento sola, tengo tantas cosas en la cabeza y estoy lidiando con las expectativas de mis padres. Supongo que me falta apoyo, pero no sé a quién acudir.', 'Lamento que te sientas así hoy. Es natural tener días oscuros, especialmente cuando estás enfrentando una lucha tan complicada. El juego puede parecer un refugio, pero el hecho de que te des cuenta de que no está resolviendo tus problemas es un paso importante. Es bueno buscar apoyo y compartir estas cargas; no tienes que enfrentarlo sola. Considera las personas a tu alrededor que podrían ofrecerte la compañía y la comprensión que necesitas.', 'Processed');
INSERT INTO "Journalings" ("Id", "TreatmentId", "Date", "EntryType", "Transcription", "AiReplyText", "State") VALUES ('b593bded-84ec-5195-9b6f-2908fe0b025f', '12b01eac-bec4-5767-96bb-f447917bb7b1', '2026-06-19', 'text', 'Día 4: Hoy, tuve una pequeña victoria. Decidí salir a caminar con un amigo, aunque la idea no me emocionaba al principio. Nos sentamos en un parque, y un rato después, empecé a sentirme más viva. Hablar con alguien, compartir risas, fue increíble. Me costó un poco dejar el celular en casa y no estar pendiente de las notificaciones, pero creo que valió la pena. Al regresar, me sentí diferente, un poco más ligera, como si hubiera liberado una porción de la presión que sentía. Me doy cuenta de que hay vida más allá de las pantallas; es emocionante, aunque me asusta también.', '¡Qué gran noticia! Celebrar esas pequeñas victorias es tan importante. La conexión humana es invaluable y puede ayudarte a ver el mundo desde una perspectiva nueva. También es impresionante que hayas podido dejar el celular atrás; eso muestra tu determinación para hacer un cambio. Sigue explorando esos momentos que te hacen sentir más viva; cada uno de ellos cuenta en tu camino hacia la recuperación.', 'Processed');
INSERT INTO "Journalings" ("Id", "TreatmentId", "Date", "EntryType", "Transcription", "AiReplyText", "State") VALUES ('03e9cf07-884e-5b9f-bb8e-43be29822770', '12b01eac-bec4-5767-96bb-f447917bb7b1', '2026-06-20', 'text', 'Día 5: Pues, después de la alegría de ayer, hoy fue un desliz. La verdad es que me costó volver a conectarme con esa sensación positiva. Pasé toda la tarde navegando en redes, y no puedo dejar de sentirme frustrada. A veces pienso que no serviré para esto, que jamás podré cambiar. Fue otro día donde perdí el hilo de lo que realmente importa. A la noche, ya no me quedaba energía, y me sentí tan abatida. Definitivamente, me cuestioné si siquiera valía la pena seguir. Estaba a punto de rendirme, pero hice un esfuerzo por reflexionar. Tengo que seguir intentándolo.', 'Es natural tener días así, especialmente después de un avance positivo. El proceso de recuperación rara vez es lineal, y te encuentras en un camino que tiene altos y bajos. Es bueno que a pesar de la frustración puedas reflexionar sobre tus emociones y reconocer el deseo de intentar de nuevo. Sé que puedes superar estos desafíos; cada paso cuenta, independientemente de lo pequeño que pueda parecer. Tienes la fuerza para seguir.', 'Processed');
INSERT INTO "Journalings" ("Id", "TreatmentId", "Date", "EntryType", "Transcription", "AiReplyText", "State") VALUES ('9f925f70-763f-5e95-b8d6-420b0b9f9dcd', '12b01eac-bec4-5767-96bb-f447917bb7b1', '2026-06-21', 'audio', 'Día 6: Hoy fue un día menos caótico. Me propuse dedicar tiempo a un pasatiempo que solía disfrutar: la pintura. Sabía que debía hacer algo para alejarme de la pantalla. Pasé unas horas mezclando colores y sintiéndome creativa. Fue liberador de cierta manera; podía olvidar un poco las presión y la ansiedad. Sin embargo, después, cuando miré el reloj, me sorprendí de cuánto tiempo había pasado. Los días se acaban rápidamente, y eso me asustó un poco. Pero, sin embargo, recordar que puedo disfrutar de otras cosas me ha dado un poco de esperanza.', 'Qué bonito es escuchar que encontraste un tiempo para disfrutar de la pintura. Explorar tus pasiones es una forma maravillosa de crear un espacio lejos de las redes sociales y los videojuegos. Puede que te sorprendas de la rapidez con la que pasa el tiempo, pero lo importante es que en esos momentos de creatividad encontraste calma y bienestar. Sigue explorando estas nuevas formas de expresión; son pasos fabulosos hacia adelante.', 'Processed');
INSERT INTO "Journalings" ("Id", "TreatmentId", "Date", "EntryType", "Transcription", "AiReplyText", "State") VALUES ('39478cb0-d66b-57b4-8736-f01baf6e873f', '12b01eac-bec4-5767-96bb-f447917bb7b1', '2026-06-23', 'text', 'Día 7: Hoy me sentí sumamente reflexiva. La verdad es que, al salir de la rutina habitual, he comenzado a preguntarme por qué me aferro tanto a las redes y los juegos, y lo que realmente me aportan. Realmente tengo miedo de quedarme sola, o que la gente me olvide. Luego, el tema me llevó a pensar en cómo me siento en torno a mis amistades. Al final, pasé la tarde viendo una serie con mi madre, lo que me ayudó a conectarme más con ella. Fue extraño, pero también reconfortante. Empecé a repensar qué relaciones realmente valen la pena.', 'Es maravilloso que estés cuestionando tus relaciones y reflexionando sobre lo que realmente valoras. Muchas veces las amistades en línea pueden distorsionar nuestra percepción de conexión. Es valioso conectar con la gente en la vida real, como hiciste al pasar tiempo con tu madre. Permítete explorar esas emociones profundamente; cada vez que te das la oportunidad de reflexionar, das un paso hacia el autoconocimiento y la sanación.', 'Processed');
INSERT INTO "Journalings" ("Id", "TreatmentId", "Date", "EntryType", "Transcription", "AiReplyText", "State") VALUES ('38f1e598-b7b4-52fa-8ad3-cf432efca60d', '12b01eac-bec4-5767-96bb-f447917bb7b1', '2026-06-25', 'audio', 'Día 8: Los pensamientos han estado más claros hoy. A pesar de que no he dejado de usar las redes, he tratado de no sentirme culpable por ello. En lugar de eso, he trabajado en aceptar mis sentimientos de ansiedad y soledad. A veces, solo quiero desconectarme y gritar, pero no sirve de nada, solo el desahogo momentáneo. Ehn... también encontré la idea de establecer metas más pequeñas, como limitar mi tiempo cada día, más realista. He estado haciendo ejercicios de respiración para calmarme cuando siento la urgencia de mirar mi teléfono, y ha sido un descubrimiento interesante.', 'Aceptarte a ti misma y tus emociones es un gran paso hacia adelante. No hay necesidad de vivir con culpa por tus acciones; lo importante es el deseo de mejorar y aprender de ti misma. Las metas pequeñas son absolutamente útiles; recuerda que cada pequeño logro te acerca a tu objetivo mucho más grande. Me alegra escuchar que practicar ejercicios de respiración ha sido útil para ti; sigue usándolos, esos momentos de calma son valiosos en este camino.', 'Processed');
INSERT INTO "Journalings" ("Id", "TreatmentId", "Date", "EntryType", "Transcription", "AiReplyText", "State") VALUES ('f67f977f-90b7-5008-a93e-2f998e17c32e', '12b01eac-bec4-5767-96bb-f447917bb7b1', '2026-06-27', 'text', 'Día 9: Hoy quise probar algo diferente. Asistí a una clase de yoga con una amiga. Al principio, me sentía un poco extraña y fuera de lugar, pero poco a poco me fui integrando. La práctica me ayudó a estar más centrada, y me olvidé un poco del caos que a menudo siento. Sin embargo, al final de la clase, el primer impulso fue volver a mirar mi celular, como si estuviera en modo automático. Esa lucha constante entre querer cambiar y los viejos hábitos es realmente frustrante. Sin embargo, el hecho de haber salido y probado algo nuevo me ha dado un poco de energía.', 'Qué hermoso que hayas decidido salir de tu zona de confort al asistir a la clase de yoga. Está claro que estás explorando nuevas formas de cuidar tanto tu mente como tu cuerpo, lo cual es increíblemente positivo. Es normal sentir la tentación de volver a tus hábitos anteriores; es parte de la naturaleza humana. Lo importante es que cada esfuerzo cuenta, y te animamos a seguir probando nuevas experiencias que te conecten con tu bienestar.', 'Processed');
INSERT INTO "Journalings" ("Id", "TreatmentId", "Date", "EntryType", "Transcription", "AiReplyText", "State") VALUES ('d08f6964-1d7b-529c-b750-3f1227b57fd5', '12b01eac-bec4-5767-96bb-f447917bb7b1', '2026-06-29', 'text', 'Día 10: Hoy me siento en una mezcla de emociones. Por un lado, estoy contenta porque he sentido que tengo un poco más de control sobre mis hábitos. He estado usando la meditación para calmarme y eso ha hecho maravillas. Sin embargo, a veces me asaltan pensamientos como que no estoy haciendo suficiente, que todos los demás están avanzando y yo no. Es difícil no hacer comparaciones y recordar que cada uno tiene su propio tiempo. Creo que estoy empezando a aceptar que es un proceso lento y que, al final del día, lo más importante es seguir intentándolo.', 'Es absolutamente genial escuchar que te sientes con más control y que estás utilizando la meditación para tu bienestar emocional. Las comparaciones son algo con lo que muchos lidiamos, pero recuerda que cada persona está en su propio viaje. Aceptar que el proceso es lento es una muestra de madurez y autocompasión. Sigue intentándolo y, por favor, reconoce tus logros, por pequeños que sean; estás haciendo un trabajo increíble mientras navegas por este desafío.', 'Processed');
INSERT INTO "Journalings" ("Id", "TreatmentId", "Date", "EntryType", "Transcription", "AiReplyText", "State") VALUES ('2224f483-84b0-5583-9230-a848af821b49', '323ff4ff-30b3-5eec-b040-3b5e48459be0', '2026-06-16', 'text', 'Día 1: Hoy fue un día complicado, eh... no sé, siento que el peso de la semana me está afectando. Estuve en una reunión de trabajo y, sinceramente, no puedo sacudirme esta sensación de ansiedad. Al final, cuando llegué a casa, sabiendo que tenía una botella de vino en la nevera, me rendí. Me dije que solo sería una copa, pero acabé vaciando toda la botella. No sé por qué sigo cayendo en esto. Mi esposa me miró con una mezcla de decepción y preocupación, lo que me hizo sentir aún peor. Ahora tengo un nudo en el estómago, y me pregunto si realmente puedo cambiar esto.', 'Pedro, es comprensible que sientas esta presión después de un día tan agotador. La ansiedad puede ser desbordante y, a veces, recurrir al alcohol parece ser la única salida. Quiero que sepas que estás dando un paso importante al reflexionar sobre tu comportamiento y sus efectos en tu vida. Es normal sentirte así en este proceso, pero recuerda que cada día es una nueva oportunidad para enfrentar estos desafíos.', 'Processed');
INSERT INTO "Journalings" ("Id", "TreatmentId", "Date", "EntryType", "Transcription", "AiReplyText", "State") VALUES ('6c84cfbf-29d6-5ecd-b4c7-9d9f1c62f3c8', '323ff4ff-30b3-5eec-b040-3b5e48459be0', '2026-06-18', 'audio', 'Día 2: No me siento mejor... de hecho, hoy fue peor. Tuve una discusión con mi esposa por mi consumo de alcohol. Ella me dice que está preocupada, pero no puedo evitar sentirme atacado. Al final del día, salí con unos colegas después del trabajo, y, eh, terminamos en un bar. Pedí un trago tras otro, y ahora me siento vacío. Es como si la euforia se fuera en un instante y ahora solo tengo remordimientos. Supongo que tengo que enfrentar esta realidad, pero no sé si estoy listo para ello.', 'Lamento que estés pasando por un momento tan difícil, Pedro. Los conflictos en casa pueden ser increíblemente desalentadores, especialmente cuando sientes que estás luchando contra algo que no puedes controlar. Es normal sentirse perdido y preocupado por el impacto en tus relaciones. Permítete sentir lo que estás sintiendo; está bien tener dudas. Este proceso lleva tiempo, y cada pequeño movimiento hacia adelante cuenta.', 'Processed');
INSERT INTO "Journalings" ("Id", "TreatmentId", "Date", "EntryType", "Transcription", "AiReplyText", "State") VALUES ('b3e77787-ef48-5dc7-810b-a982235580cf', '323ff4ff-30b3-5eec-b040-3b5e48459be0', '2026-06-20', 'audio', 'Día 3: Hoy decidí que no iba a beber, al menos eso intenté. Pasé el día enfocándome en el trabajo, y aunque sentí la ansiedad golpeando de nuevo, logré resistir. Pero cuando llegué a casa, vi a mi esposa hacer una cena que me encantaba, y, eh... no sé, la tentación fue demasiada. Con el vino sirviéndose, me pregunté cómo podía disfrutarla sin un trago. Terminé tomando solo un par de copas, pero todavía me siento como si hubiera fallado. Al menos no fue una botella entera, supongo. Pero mi diálogo interno sigue siendo muy crítico.', 'Es un paso positivo que hayas intentado resistir hoy, Pedro. Reconocer la tentación y la ansiedad que sientes es un gran avance en sí mismo. Es completamente natural querer disfrutar de los placeres como una buena cena con un trago, y cada pequeño paso cuenta. No seas tan duro contigo mismo; estás aprendiendo y creciendo. La autocompasión es clave para este viaje.', 'Processed');
INSERT INTO "Journalings" ("Id", "TreatmentId", "Date", "EntryType", "Transcription", "AiReplyText", "State") VALUES ('3fc2e0f6-88c5-5cbc-9a69-07620c2514ed', '323ff4ff-30b3-5eec-b040-3b5e48459be0', '2026-06-21', 'text', 'Día 4: Hoy desperté sintiéndome culpable por anoche. Hice una lista de todo lo que tengo que perder si sigo con esto, eh... mi familia, mi salud, mi negocio. Pero en lugar de motivarme, me sentí abrumado. Así que, nuevamente, me dejé llevar por el estrés del trabajo, y al llegar a casa, esta vez no pude resistir. Abrí una botella y la terminé, y después la culpa se intensificó. Estoy atrapado en este ciclo, y no sé cómo romperlo. Ahora estoy aquí, con el peso sobre mis hombros.', 'Pedro, reconocer que te sientes atrapado es el primer paso para cambiar este ciclo. La culpa puede ser muy pesada, pero recuerda que el cambio no ocurre de la noche a la mañana. Es posible que hoy no hayas alcanzado tu objetivo, pero estás reflexionando sobre tus decisiones y sus consecuencias. Permítete sentir estas emociones, y, lo más importante, no dejes que te definan. La perseverancia es clave.', 'Processed');
INSERT INTO "Journalings" ("Id", "TreatmentId", "Date", "EntryType", "Transcription", "AiReplyText", "State") VALUES ('76ea8f86-10de-51bd-90bf-56454d9d0cda', '323ff4ff-30b3-5eec-b040-3b5e48459be0', '2026-06-22', 'text', 'Día 5: Hoy fue un día particularmente difícil. Después de lo de anoche, me sentí más ansioso que nunca. Por la mañana, intenté meditar por unos minutos, pero mi mente estaba a mil por hora. Durante la tarde, un cliente vino a oficina claramente borracho, y me hizo sentir incómodo. Me recordó a mí mismo y no me gustó. Volviendo a casa, después de un día estresante, sentí una necesidad abrumadora de buscar alivio en el alcohol. Pero, en lugar de eso, llamé a un amigo y hablamos un rato sobre cómo me he estado sintiendo. Supongo que eso fue un avance, ¿no? No lo sé.', 'Ese fue un gran avance, Pedro. Hablar con un amigo sobre tus sentimientos es un paso significativo hacia la identificación de tus emociones y la búsqueda de apoyo. Es natural enfrentar días difíciles, especialmente cuando te enfrentas a recuerdos desafiantes, pero cada vez que eliges buscar una alternativa al alcohol, como lo hiciste hoy, es un paso hacia el cambio positivo. Sigue así, sigue abriéndote. Eres más fuerte de lo que crees.', 'Processed');
INSERT INTO "Journalings" ("Id", "TreatmentId", "Date", "EntryType", "Transcription", "AiReplyText", "State") VALUES ('96f26d90-c29f-5b7d-a08d-f55e1a767549', '323ff4ff-30b3-5eec-b040-3b5e48459be0', '2026-06-23', 'audio', 'Día 6: Hoy fue una mezcla. Me desperté sintiéndome orgulloso de haber hablado con mi amigo, pero la ansiedad empezó a aumentar por la tarde cuando me enfrenté a un gran proyecto en el trabajo. Para desahogarme, decidí salir a correr. Fue liberador, pero luego, al regresar, aunque no bebí, el impulso estaba allí. Pasé la noche en casa, y aunque resistí la tentación, sentí el deseo presente. ¿Por qué es tan difícil creer que puedo hacerlo?', 'Pedro, lo que describes es una respuesta común en tu proceso de cambio. Los altibajos son parte natural del viaje, y es completamente válido sentirse orgulloso por momentos de resistencia, al mismo tiempo que lidias con esos impulsos. El haber encontrado una alternativa positiva como correr, te está ayudando a reducir el estrés. La autocompasión y paciencia contigo mismo son vitales en este proceso; cada día que resistes es un paso más hacia la transformación que deseas.', 'Processed');
INSERT INTO "Journalings" ("Id", "TreatmentId", "Date", "EntryType", "Transcription", "AiReplyText", "State") VALUES ('ed2b923e-6315-5a31-94d9-70efdc2d6929', '323ff4ff-30b3-5eec-b040-3b5e48459be0', '2026-06-24', 'text', 'Día 7: ¡No puedo creer que ya haya pasado una semana! He tenido altibajos, como siempre, eh... pero hoy está siendo un día bueno. He decidido tomar un enfoque más activo en mis pensamientos. Encontré un libro sobre la adicción al alcohol y comencé a leerlo. Me da otra perspectiva sobre mi relación con la bebida. Aunque tengo miedo de caer de nuevo, siento que estoy aprendiendo más sobre mí mismo. Quizá no todo está perdido. Tal vez pueda encontrar un camino.', '¡Eso es maravilloso, Pedro! Es un gran avance que estés buscando conocimiento y cómo puede ayudarte a entender mejor la situación. Leer sobre la adicción puede ofrecerte nuevas herramientas y perspectivas. Reconocer que hay un camino hacia adelante y aprender de tus experiencias pasadas es un poderoso paso hacia la recuperación. Cada día que dedicas a tu crecimiento personal es una inversión en una vida más plena y satisfactoria.', 'Processed');
INSERT INTO "Journalings" ("Id", "TreatmentId", "Date", "EntryType", "Transcription", "AiReplyText", "State") VALUES ('c0c564f2-eb32-502c-84ff-3ef73cd1c46c', '323ff4ff-30b3-5eec-b040-3b5e48459be0', '2026-06-25', 'text', 'Día 8: Hoy sentí un gran desafío en el trabajo. Un cliente me puso en una situación tensa, y noté cómo mi mente automáticamente buscaba el alivio del alcohol. Sin embargo, decidí tomar un tiempo para respirar y salir a dar una vuelta. Eso realmente me ayudó, eh... y aunque llegué a casa con ganas de tomar algo, me acordé de lo que he estado aprendiendo y elegí preparar una bebida sin alcohol. Puede que no sea mucho, pero no sé, me siento bien. Tal vez un pequeño paso, pero un paso al fin.', 'Esos pequeños pasos, Pedro, son lo que realmente cuenta en tu camino hacia el cambio. Has demostrado tu capacidad de enfrentar situaciones desafiantes de una manera más saludable y positiva. Elegir opciones alternativas, como una bebida sin alcohol, muestra tu creciente fortaleza y determinación. Celebra esos logros, por pequeños que parezcan; cada uno de ellos contribuye a tu cambio personal. Estás haciendo un gran trabajo.', 'Processed');
INSERT INTO "Journalings" ("Id", "TreatmentId", "Date", "EntryType", "Transcription", "AiReplyText", "State") VALUES ('3e6fb1ef-9b5b-50ce-9f20-9d53941dbfc2', '323ff4ff-30b3-5eec-b040-3b5e48459be0', '2026-06-27', 'text', 'Día 9: Hoy me enfrenté a una gran tentación. Estuve en una fiesta con algunos colegas, y todos estaban bebiendo. Me sentía un poco fuera de lugar, eh... la presión era intensa. Pero decidí aferrarme a mi decisión y no tomar nada. No fue fácil, pero conversé con algunos de los asistentes, y me centré en disfrutar el momento sin alcohol. Regresé a casa sintiéndome aliviado, aunque todavía con esos temores que no desaparecen del todo. Supongo que estoy aprendiendo a lidiar con los momentos difíciles.', 'Pedro, lo que hiciste hoy es un testimonio de tu creciente autocontrol y valentía. Enfrentar la tentación en un entorno social puede ser increíblemente difícil, pero lograste mantenerte firme en tu decisión. Lo más importante es que encontraste formas de disfrutar el momento sin recurrir al alcohol. Cada vez que haces esto, fortaleces tu camino hacia una relación más saludable con la bebida. Sigue adelante con ese espíritu.', 'Processed');
INSERT INTO "Journalings" ("Id", "TreatmentId", "Date", "EntryType", "Transcription", "AiReplyText", "State") VALUES ('252f1b03-6bdc-5364-95f8-9a6f97d1e169', '323ff4ff-30b3-5eec-b040-3b5e48459be0', '2026-06-29', 'text', 'Día 10: Hoy, al reflexionar sobre estas dos semanas, siento que he recorrido un largo camino. He tenido mis altos y bajos, pero es alentador ver cómo puedo lidiar con la ansiedad sin el alcohol. Les hablé a algunos amigos sobre lo que estoy sintiendo, y la respuesta ha sido realmente inspiradora. Ellos me brindan apoyo. Claro, no es fácil y todavía tengo miedo de los retrocesos, pero al menos siento que estoy aprendiendo a creer más en mí mismo. Creo que eso es un verdadero avance.', 'Es un gran logro que estés reconociendo todo lo que has aprendido en estas dos semanas, Pedro. La capacidad de hablar con tus amigos sobre tus luchas y recibir su apoyo es invaluable en tu proceso. Aprender a manejar la ansiedad sin el alcohol es una victoria significativa que refleja tu determinación para mejorar. Sigue confiando en este camino; en cada paso, estás construyendo una versión más fuerte y resiliente de ti mismo. ¡Sigue así!', 'Processed');
